// Request is one line of ADR 005's request log: timestamp, authority,
// method, path, status, duration, upstream port, and the log's own count of
// the record. Metadata only — voya reads no payloads (ADR 003).
type Request struct {
	state     protoimpl.MessageState `protogen:"open.v1"`
	At        *timestamppb.Timestamp `protobuf:"bytes,1,opt,name=at,proto3" json:"at,omitempty"`
	Authority string                 `protobuf:"bytes,2,opt,name=authority,proto3" json:"authority,omitempty"`
	Method    string                 `protobuf:"bytes,3,opt,name=method,proto3" json:"method,omitempty"`
	Path      string                 `protobuf:"bytes,4,opt,name=path,proto3" json:"path,omitempty"`
	// The routing status voya wrote, or the upstream's.
	Status   int32                `protobuf:"varint,5,opt,name=status,proto3" json:"status,omitempty"`
	Duration *durationpb.Duration `protobuf:"bytes,6,opt,name=duration,proto3" json:"duration,omitempty"`
	// 0 when voya answered without forwarding.
	UpstreamPort uint32 `protobuf:"varint,7,opt,name=upstream_port,json=upstreamPort,proto3" json:"upstream_port,omitempty"`
	// The record's place in the daemon's log: a per-daemon counter, assigned
	// as the record is appended to the buffer, starting at 1 so that 0 means
	// a daemon that predates the field rather than its first record (#191).
	// It is what `voya log -f` tells two records apart by — the timestamp
	// cannot, on a clock coarser than the gap between two requests. It counts
	// what the daemon recorded, not what one client was served: WatchRequests
	// skips no number, because a follower it cannot keep up with is ended with
	// resource_exhausted rather than served a thinned stream, while a jump
	// between two ListRequests calls is what the buffer overwrote in between.
	// Restarting voya restarts the count, like the log it counts.
	Sequence      uint64 `protobuf:"varint,8,opt,name=sequence,proto3" json:"sequence,omitempty"`
	unknownFields protoimpl.UnknownFields
	sizeCache     protoimpl.SizeCache
}

